def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp_def_total = sum(1 for _, o in history if o == 'D')
    my_def_total = sum(1 for m, _ in history if m == 'D')

    # Endgame
    if n >= 99:
        return 'D'
    if n >= 95:
        if opp_def_total < n * 0.2:
            return 'D'
        if history[-1][1] == 'D':
            return 'D'
        return 'C'

    # If opponent is extremely defective, defect always (after some rounds)
    if n > 20 and opp_def_total > n * 0.8:
        return 'D'

    # Probe for allC at round 10
    if n == 10 and opp_def_total == 0:
        return 'D'
    if n == 11 and history[9][0] == 'D' and history[9][1] == 'C' and opp_def_total == 0:
        return 'C'
    if n > 11 and opp_def_total == 0:
        if history[9][0] == 'D' and history[9][1] == 'C' and history[10][0] == 'C' and history[10][1] == 'C':
            return 'D'
        return 'D'

    # Streak recovery: if opponent has 4+ consecutive defections, occasionally cooperate.
    consec_opp_def = 0
    for i in range(n-1, -1, -1):
        if history[i][1] == 'D':
            consec_opp_def += 1
        else:
            break

    if consec_opp_def >= 4:
        if rng.random() < 0.35:
            return 'C'
        return 'D'

    # Standard TFT with forgiveness
    my_last, opp_last = history[-1]
    if opp_last == 'D':
        if my_last == 'D':
            return 'C'
        else:
            return 'D'
    else:
        if my_last == 'D':
            return 'C'
        return 'C'
